def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    from typing import Tuple
    from pathlib import Path
    import os

    if not all(isinstance(part, str) for part in cmd):
        raise ValueError("All elements of the input tuple must be strings")

    normalized_cmd = cmd.copy()
    if cmd and normalized_cmd[0] in ['', '/']:
        normalized_cmd = normalized_cmd[1:]  # remove the first command if it's empty or a slash

    if os.name == "nt":
        # Fix for the shebang windows does not parse
        for index, part in enumerate(normalized_cmd):
            if part.startswith("#!") and os.path.exists(os.path.dirname(part)):
                normalized_cmd[index] = os.path.dirname(part)

        #Handle deep-path shebangs
        for index, part in enumerate(normalized_cmd):
            if part.startswith("#!") and os.path.exists(part):
                with open(part, 'r') as f:
                    shebang_line = f.readline().strip()
                    if shebang_line.startswith("#!"):
                        normalized_cmd[index] = shebang_line.split()[1]

    return tuple(normalized_cmd)

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.
    """
    def wrapper(f):
        data = cache.get(key, None)
        if data is not None:
            return data
        try:
            data = f()
            cache.set(key, data)
        except Exception as e:
            if lock:
                lock.acquire()
            cache.set(key, None)  # Clear cache on error
            if lock:
                lock.release()
            raise e
        return data
    return wrapper

import time

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    cache = dict()
    keys_order = []

    def memoize(func):
        def wrapper(*args, **kwargs):
            key = (args, frozenset(kwargs.items()))
            if key not in cache or timer() - cache[key][0] > ttl:
                result = func(*args, **kwargs)
                cache[key] = (timer(), result), 0 if not typed else cache[key][1]
            # Pop the key when it reaches our size limit
            if len(cache) > maxsize:
                cache.pop(keys_order.pop(0))
            # Update the order of keys to reflect TTL
            for i, (k, (t, r), order) in enumerate(cache):
                if k == key:
                    cache[i] = ((timer() - t), r), order
                    break
        return wrapper

    return memoize

