@staticmethod
def append_text_to_file(file_name, text_buffer, encoding, overwrite=False):
    def _write_file(file_path, data, overwrite):
        try:
            f = open(file_path, 'w' if overwrite else 'a')
            f.write(data)
            f.close()
            return len(data)
        except Exception as e:
            raise Exception(f"Failed to write file {file_path}: {e}")

    if not os.path.exists(file_name) and not overwrite:
        raise FileNotFoundError(f"File {file_name} does not exist and overwrite is disabled.")
    try:
        return _write_file(file_name, text_buffer.encode(encoding), overwrite)
    except Exception as e:
        raise Exception(f"Failed to append text to file {file_name}: {e}")

