def minimalBases(classes):
    if not classes:
        return []

    base_set = set(classes)

    # Adjusting for duplicates
    while classes != base_set:
        for class_ in classes:
            base_set.add(class_.__bases__[0])
        classes = base_set.copy()

    return sorted(list(base_set))

