def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("Both arguments must be dictionaries")

    def _nested_difference(sub_d1, sub_d2, depth):
        result = {}
        for key in sub_d1:
            if key not in sub_d2:
                result[key] = sub_d1[key]
            elif depth > 0 and isinstance(sub_d1[key], dict) and isinstance(sub_d2[key], dict):
                result[key] = _nested_difference(sub_d1[key], sub_d2[key], depth - 1)
            elif sub_d1[key] != sub_d2[key]:
                result[key] = sub_d1[key]
        for key in sub_d2:
            if key not in sub_d1:
                result[key] = sub_d2[key]
        return result

    return _nested_difference(d1, d2, level) if level > 0 else None

def fill(self, coord, weight=1):
    if not isinstance(coord, tuple) or len(coord) != 2:
        raise ValueError("Coord must be a tuple of two numeric values")
    if weight < 0:
        raise ValueError("Weight must not be negative")

    # Ensure the histogram is non-empty before filling
    if not self.histogram:
        self.histogram = {coord: 0}  # Start with an empty histogram

    # Modify the histogram at the provided coordinate with the given weight
    if coord in self.histogram:
        self.histogram[coord] += weight
    else:
        self.histogram[coord] = weight

