    return observer_schema

def format(self, sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]):
    if not isinstance(sql, str) and not isinstance(sql, bytes):
        raise ValueError("SQL query must be a string or bytes")
    if not isinstance(params, (dict, list)) or (isinstance(params, dict) and not all(isinstance(k, str) or isinstance(k, int) for k in params)):
        raise ValueError("Parameters must be a dictionary or list of strings and integers")

    formatted_sql = sql
    converted_params = params

    if self.SQLParams.in_style == "named":
        if not isinstance(params, dict):
            raise TypeError("For named parameter style, parameters must be a dictionary")
        if len(params) != len(self.columns):
            raise ValueError("Number of parameters does not match number of columns")
        for key, value in params.items():
            formatted_sql = formatted_sql.replace(f":{key}", f"{key}")
        converted_params = {.column_name: value for column_name, value in params.items()}
    elif self.SQLParams.in_style == "ordinal":
        if not isinstance(params, list):
            raise TypeError("For ordinal parameter style, parameters must be a list")
        if len(params) != len(self.columns):
            raise ValueError("Number of parameters does not match number of columns")
        for i in range(len(params)):
            formatted_sql = formatted_sql.replace(f":p{i+1}", f"{params[i]}")
        converted_params = params
    else:
        converted_params = params

    return formatted_sql, converted_params

def formatmany(
    self,
    sql: AnyStr,
    many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    out_params = []
    result_sql = sql % {"%s": param for param in many_params[0].values()}
    for params in many_params[1:]:
        out_params.append(dict((str(i), val) for i, val in enumerate(params.values())))
    return result_sql, out_params

