import zipfile
from typing import Dict

def _explore_zipfile(zip_path: str) -> Dict[str, dict]:
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path

    Returns
    -------
    dict
    """
    if not zipfile.is_zipfile(zip_path):
        raise ValueError("The provided path is not a valid zip file.")

    packages_data = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zip_ref:
            for file_info in zip_ref.infolist():
                file_name = file_info.filename
                if file_name.endswith('.xml'):  # Assuming files with .xml extension mean data packages
                    base_name = file_name.rsplit('.', 1)[0]
                    if base_name in packages_data:
                        packages_data[base_name].update(zip_ref.read(file_name))
                    else:
                        packages_data[base_name] = {file_name: zip_ref.read(file_name)}
    except zipfile.BadZipFile:
        raise ValueError("The provided file is not a valid zip file.")
    except Exception as e:
        raise AssertionError("An unexpected error occurred: ", e)

    return packages_data

