def pretty(self, indent=0, debug=False):
    if not hasattr(self, '__dict__') or not self.__dict__:
        return self.__class__.__name__ + '()'
    result = ''
    for key in sorted(self.__dict__.keys()):
        value = self.__dict__[key]
        if debug and (self.__dict__.get('__debug__') is False or not isinstance(value, (str, int, float, bool, list, dict))):
            value = 'unknown'
        result += ' ' * indent + key + ': '
        result += self._format_value(value, indent + 2)
        if key != list(self.__dict__.keys())[-1]:
            result += '\n'
    return '{' + result.rstrip() + '}'

def _format_value(self, value, indent=0):
    if isinstance(value, dict):
        return '{' + self._format_dict(value, indent) + '}'
    elif isinstance(value, list):
        return '[' + self._format_list(value, indent) + ']'
    elif isinstance(value, str):
        return f"'{value}'"
    elif isinstance(value, (int, float)):
        return str(value)
    elif isinstance(value, bool):
        return str(value).lower()
    else:
        return 'unknown'

def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.
        """
    if not isinstance(hook, HookType):
        raise ValueError("hook must be of type HookType")

    def decorator(listener):
        def wrapper(*args, **kwargs):
            if hook in self.registry:
                for handler in self.registry[hook]:
                    handler(*args, **kwargs)
            self.registry.setdefault(hook, []).append(listener)
        return wrapper
    return decorator

