import subprocess

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    try:
        if cwd is None:
            cwd = '.'

        if verbose:
            print(f"Executing command: {commands} with arguments {args} in {cwd}")

        if hide_stderr:
            stderr = subprocess.PIPE
        else:
            stderr = subprocess.STDOUT

        process = subprocess.Popen(commands, args=args, cwd=cwd, stdout=subprocess.PIPE, stderr=stderr, env=env)
        # Wait for the process to complete
        stdout, stderr = process.communicate()
        # Decode the output and handle exceptions
        if process.returncode != 0:
            raise Exception(f"Command failed with return code {process.returncode}: {stderr.decode('utf-8')}")

        if verbose:
            print(f"Command output: {stdout.decode('utf-8')}")

        return stdout, stderr
    except subprocess.CalledProcessError as e:
        if verbose:
            print(f"Error running command: {e}")
        return e.stderr, e.stdout

