def deep_merge_nodes(nodes):
    from ruamel.yaml.nodes import MappingNode, ScalarNode
    from ruamel.yaml.util import merge_docs
    from ruamel.yaml import YAML

    def merge_nodes(nodes):
        result = {}
        for key, value in nodes:
            if key in result:
                if not isinstance(result[key], MappingNode):
                    result[key] = [result[key], value]
                else:
                    merge_docs(result[key], value)
            else:
                result[key] = value

        return result

    merged_nodes = []
    for node in nodes:
        key, value = node
        if isinstance(key, ScalarNode) and isinstance(value, (MappingNode,)):
            merged_nodes += merge_nodes((key, value,))
        else:
            merged_nodes.append(node)

    # Create a new YAML object and load the merged nodes
    yaml = YAML()
    yaml.preserve_quotes = True
    config = yaml.load(merged_nodes)
    return config

