import re

def size_to_bytes(size: str) -> int:
    if not re.match(r'^\d+(K|M|G)$', size):
        raise ValueError('Invalid input size')

    units = {'K': 1024, 'M': 1048576, 'G': 1073741824}
    number = float(size[:-1])
    return int(number * units[size[-1]])

