def _replace_url_args(url, url_args):
    if not isinstance(url, str) or not isinstance(url_args, dict):
        raise ValueError("Input must be a URL and a dictionary of URL arguments.")

    for key, value in url_args.items():
        if url.find(f"&{key}=") > -1:
            url = url.replace(f"&{key}={value}", f"&{key}=new_value")
        elif url.find(f"&{key}=") == -1 and url.find(f"?{key}=") > -1:
            url = url.replace(f"?{key}={value}", f"?{key}=new_value")
        elif url.find(f"?{key}=") == -1 and url.find(f"&{key}=") > -1:
            url = url.replace(f"{key}={value}", f"{key}=new_value")
        elif url.find(f"?{key}=") == -1 and url.find(f"&{key}=") == -1:
            url = url + f"?{key}=new_value"
        else:
            raise ValueError("Invalid URL format.")

    return url

