def was_processed(processed, path_name, verbose):
    if verbose:
        print("Processing:", path_name)

    absolute_path = os.path.abspath(path_name)
    if os.path.exists(absolute_path):
        if absolute_path in processed:
            if verbose:
                print("File or directory already processed:", absolute_path)
            return True
        else:
            processed.add(absolute_path)
            if verbose:
                print("Added to processed:", absolute_path)
            return False
    else:
        if verbose:
            print("Path does not exist:", absolute_path)
        return False

