    for i in range(len(vertices)):
        vertex = vertices[i]
        next_vertex = vertices[(i + 1) % len(vertices)]
        prev_vertex = vertices[(i - 1) % len(vertices)]
        result.append((vertex, next_vertex, prev_vertex))

    return tuple(result)

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if not alphabet or len(alphabet) < 2:
        raise ValueError("Alphabet must contain at least two characters.")

    if padding is not None and padding < 0:
        raise ValueError("Padding cannot be a negative number.")

    if number < 0:
        sign = '-'
        number = abs(number)
    else:
        sign = ''

    if padding:
        number = number * (10 ** padding)

    result = []
    while number > 0:
        digit = number % len(alphabet)
        result.insert(0, alphabet[digit])
        number //= len(alphabet)

    return sign + ''.join(result)

