import re

def regex_dict(item):
    """
    Convert *.cpp keys to regex keys

    Given a dict where the keys are all filenames with wildcards, convert only
    the keys into equivalent regexes and leave the values intact.

    Example:

    rules = {
        '*.cpp':
            {'a': 'arf', 'b': 'bark', 'c': 'coo'},
        '*.h':
            {'h': 'help'}
    }
    regex_keys = regex_dict(rules)

    Args:
        item: dict to convert
    Returns:
        dict with keys converted to regexes
    """
    regex_keys = {}
    for k, v in item.items():
        if k is None:
            continue  # Ignore keys that are None
        if not isinstance(k, str):
            raise TypeError(f"Expected string key, got {type(k).__name__}")
        if not k.endswith('.cpp') or not re.match('^\*\*\.cpp', k):
            raise ValueError(f"Expected *.cpp pattern, got {k}")
        regex_keys[k] = v
    return regex_keys

