import re

def split(s, platform='this'):
    """
    Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        platform = re.compile(r'^(?P<filename>[^\s\'"]+)(?:\s+(?P<path>[^\s\'"]+))?$')
    elif platform == 1:
        platform = re.compile(r'''^
            (?:\b[A-Z][A-Z0-9_]*:[A-Z][A-Z0-9_]*[/\\](?P<path>[^\\/]*)|  # Windows/Linux
            (?:\\)  # Windows Windows\
            (?:\\\\)  # Windows Windows\\\
            (?P<path>[^\\]+$)  # Linux
        ''', re.VERBOSE)
    elif platform == 0:
        platform = re.compile(r'''^
            (?:\b[A-Z][A-Z0-9_]*:)(?P<path>[^\\]*)  # Windows CMD
        ''', re.VERBOSE)
    else:
        raise ValueError("Invalid platform value. Must be 'this', 1, 0 for auto, posix, and cmd respectively.")

    match = platform.match(s)
    if match:
        return [match.group('filename'), match.group('path')]
    else:
        raise ValueError(f"Invalid input: {s}")

