import subprocess

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    # Set up the command with arguments
    if args is not None:
        full_command = f"{' '.join(commands)} {' '.join(args)}"
    else:
        full_command = ' '.join(commands)

    # Create subprocess object
    process = subprocess.Popen(full_command, 
                             cwd=cwd, 
                             shell=True, 
                             stdout=subprocess.PIPE, 
                             stderr=subprocess.PIPE if not hide_stderr else subprocess.DEVNULL, 
                             env=env if env else None)

    # Capture the output and check the return code
    stdout, stderr = process.communicate()
    if process.returncode != 0:
        if verbose:
            print(f"Command '{full_command}' failed with return code {process.returncode}")
        else:
            print("Command failed with return code", process.returncode)
        return None
    if verbose:
        if stdout:
            print(f"Command '{full_command}' succeeded. Stdout: {stdout.decode('utf-8')}")
        if stderr:
            print(f"Command '{full_command}' succeeded. Stderr: {stderr.decode('utf-8')}")
    return stdout.decode('utf-8') if stdout else None

