class Time:
    def __init__(self, ticks, tz=None):
        self.ticks = ticks
        self.tz = tz
        self.validate()

    def validate(self):
        if not isinstance(self.ticks, int) or self.ticks < 0 or self.ticks >= 86400000000000:
            raise ValueError("ticks must be an integer between 0 and 86400000000000")

    @classmethod
    def from_ticks(cls, ticks, tz=None):
        """Create a time from ticks (nanoseconds since midnight).

        :param ticks: nanoseconds since midnight
        :type ticks: int
        :param tz: optional timezone
        :type tz: datetime.tzinfo

        :rtype: Time

        :raises ValueError: if ticks is out of bounds
            (0 <= ticks < 86400000000000)
        """
        return cls(ticks, tz)

