from zope.interface import Invalid, Interface

def verifyObject(iface, candidate, tentative=False):
    try:
        if tentative:
            return True
        if not iface.providedBy(candidate):
            raise Invalid("The candidate does not claim to provide the interface")
        result = all(isinstance(getattr(candidate, m), method_type) for m in iface.implementedBy(candidate))
        if not result:
            known_provided_methods = iface.implementedBy(candidate)
            missing_methods = [m for m in iface.implementedBy(candidate) if getattr(candidate, m) is None]
            attributes = iface.at_mostInInterfaces(candidate)
            missing_attributes = [a for a in attributes if not hasattr(candidate, a)]
            message = ""
            if missing_methods:
                message += f"Missing methods: {', '.join(missing_methods)}\n"
            if missing_attributes:
                message += f"Missing attributes: {', '.join(missing_attributes)}"
            raise Invalid(message)
        result = all(hasattr(return_value, '___name__') for return_value in [ callable(getattr(candidate, m)) for m in iface.implementedBy(candidate)])
        if not result:
            provided_methods = iface.implementedBy(candidate)
            missing_methods = [m for m in iface.implementedBy(candidate) if hasattr(getattr(candidate, m), '__call__') is not True]
            attributes = iface.at_mostInInterfaces(candidate)
            missing_attributes = [a for a in attributes if not hasattr(candidate, a)]
            message = ""
            for m in missing_methods:
                if m:
                    name = getattr(candidate, m).__name__
                    type_ = type(getattr(candidate, m))
                    message += f"Method {name} is not callable\n"
            for a in missing_attributes:
                if a:
                    name = getattr(candidate, a).__name__
                    type_ = type(getattr(candidate, a))
                    message += f"Attribute {name} is not callable\n"
            raise Invalid(message)
        return True
    except Exception as e:
        raise Invalid(str(e))

