def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    if key not in self:
        if default is __marker:
            raise KeyError(f"Key '{key}' not found in the dictionary")
        else:
            return default
    value = self[key]
    del self[key]
    return value

from collections import OrderedDict

class LRUCache(OrderedDict):
    def __init__(self, capacity: int):
        self.capacity = capacity

    def popitem(self):
        if len(self) <= self.capacity:
            return super().popitem()
        else:
            key = next(iter(self))  # Remove and return the least recently used key-value pair
            return key, self.pop(key)

def popitem(self):
        if not self._tirebucket:
            raise KeyError("popitem from empty dictionary")
        P = self._tireswaptable[max(self._tireswaptable)]
        if P._key >= 0:
            self[self._tireswaptable[P._key]]['_key'] = -1
        del self._tireswaptable[P._key]
        self._tirebucket.remove(P)
        return P._key, P._value

