from typing import Tuple, Set, Callable

def find_tags(text: str, replacer: Callable[[str], str] = None) -> Tuple[Set[str], str]:
    """
    Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    stack = []
    in_code = False
    tags = set()
    result = []

    for char in text:
        if char == '<':
            if in_code:
                result.append(char)
            else:
                stack.append(char)
                in_code = True
        elif char == '>':
            if not in_code:
                result.append(char)
            else:
                stack.pop()
                tag = ''.join(stack)
                tags.add(tag)
                in_code = False
                if replacer:
                    result.append(replacer(tag))
        else:
            if not in_code:
                result.append(char)

    return tags, ''.join(result)

def process_text_links(text):
    if not isinstance(text, str):
        raise ValueError("Text must be a string.")

    # Split the text into words
    words = text.split()

    # Process each word
    processed_words = []
    for word in words:
        # Check if the word is a link
        if word.startswith('http'):
            # Extract attributes from the link
            title, attrs = parse_link(word)
            # Linkify the word
            processed_word = linkify(word, title=title, attrs=attrs)
        else:
            # Linkify the non-link word
            processed_word = linkify(word)

        processed_words.append(processed_word)

    # Join the processed words back into a string
    return ' '.join(processed_words)


def parse_link(link):
    """Helper function to extract attributes from a link."""
    if '/' not in link:
        raise ValueError("Link must contain a forward slash ('/').")

    parts = link.rsplit('/', 1)
    title = parts[0]
    attrs = ''
    if len(parts) > 1:
        attrs = parts[1]
    return title, attrs


def linkify(word, title=None, attrs=''):
    """Helper function to linkify a word."""
    if title is None:
        title = word

    return f"[{title}]({word}{attrs})"

