def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    try:
        if method == "post":
            response = requests.post(url, data=data, timeout=timeout, *args, **kwargs)
            return response.status_code, None
        else:
            raise ValueError("Unsupported HTTP method")
    except requests.exceptions.RequestException as e:
        return None, e

def dict_insert(dic, val, key, *keys):
    if not isinstance(dic, dict):
        raise TypeError("dic must be a dictionary object")

    for k in keys[:-1]:
        if k not in dic:
            dic[k] = {}
        dic = dic[k]

    dic[keys[-1]] = val

def list_of_file_names(settings_dirs, spec_option):
    if not isinstance(settings_dirs, (list, tuple)):
        raise TypeError("settings_dirs must be a list or tuple of file paths")
    if not isinstance(spec_option, str):
        raise TypeError("spec_option must be a string")
    file_names = []
    for dir_path in settings_dirs:
        if os.path.exists(dir_path):
            for file_name in os.listdir(dir_path):
                if file_name.endswith(spec_option):
                    file_names.append(file_name)
    return file_names

