def _include_groups(self, parser_dict):
    if not isinstance(parser_dict, dict):
        raise ValueError("The input should be a dictionary")

    groups = parser_dict.get("include", [])
    if not isinstance(groups, list):
        raise ValueError("The 'include' directive should be a list")

    resolved_groups = []
    for group in groups:
        if group.startswith("!"):
            resolved_groups.append(None)
        else:
            resolved_groups.append(group)

    return resolved_groups

