def get_plugin_spec_flatten_dict_helper(spec, flat_dict):
    for key, value in spec.items():
        if isinstance(value, dict):
            get_plugin_spec_flatten_dict_helper(value, flat_dict)
        elif isinstance(value, list):
            for v in value:
                if isinstance(v, dict):
                    get_plugin_spec_flatten_dict_helper(v, flat_dict)
                else:
                    flat_dict[key] = v
        else:
            flat_dict[key] = value

def strip_root(path, root):
    if not path or not root or path.startswith(root):
        raise ValueError("Invalid path or root provided")
    return path[len(root):]
